"""Finding the stretches of opening hours nobody covers."""

from typing import Iterable, List

from hourglass.merging import merge_spans
from hourglass.models import Span
from hourglass.parsing import format_span

def is_inside(span: Span, outer: Span) -> bool:
    return (
        outer.start <= span.start and span.end <= outer.end
    )

def check_inside(spans: List[Span], opening: Span) -> None:
    """Raise ValueError for a span outside opening hours."""
    for span in spans:
        if not is_inside(span, opening):
            text = format_span(span)
            raise ValueError(f"{text} is outside opening")

def edge_points(
    spans: List[Span], opening: Span
) -> List[int]:
    points = [opening.start]
    for span in merge_spans(spans):
        points += [span.start, span.end]
    return points + [opening.end]

def uncovered_spans(
    spans: List[Span], opening: Span
) -> List[Span]:
    """The parts of opening hours that no span touches."""
    points = edge_points(spans, opening)
    pairs = zip(points[0::2], points[1::2])
    real = [pair for pair in pairs if pair[0] < pair[1]]
    return [Span(*pair) for pair in real]

def gap_label(span: Span) -> str:
    return f"gap {format_span(span)} ({span.minutes} min)"

def find_gaps(
    worked: Iterable[Span], opening: Span
) -> List[str]:
    """One label per uncovered stretch of opening hours."""
    spans = list(worked)
    check_inside(spans, opening)
    found = uncovered_spans(spans, opening)
    return [gap_label(item) for item in found]

